import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class T {
  public static void main(String[] a) {
    String[] cases = {
      "<title><b>bold</b></title><p>after</p>",
      "<textarea><div>x</div>&#65;&#x42;&amp;</textarea><i>after</i>",
      "<title>&#65;&#x4A;&#X6b;&#65 bad &#xZZ;&#0;</title>",
      "<script>&#65;<b></script><p>after</p>",
      "<style>&amp;</style>",
      "<title>no end",
      "<textarea>line1\nline2 <notatag</textarea>",
    };
    for (String c : cases) {
      Document d = Jsoup.parse(c);
      System.out.println("IN : " + c);
      System.out.println("OUT: " + d.body().html().replace("\n","\\n"));
      System.out.println("HEAD: " + d.head().html().replace("\n","\\n"));
      System.out.println("---");
    }
  }
}
EOF
javac -cp target/classes -d /tmp/t /tmp/t/T.java && java -cp target/classes:/tmp/t T

