#!/usr/bin/env python3
"""Coverage table:
- disabled optgroup and option filtering -> boundaries case -> exact ordered KeyVal list -> assertions in expect()
- single-select fallback and all-disabled omission -> boundaries case -> first enabled DOM option or no field -> single-select assertions
- disabled fieldset first-legend exception -> boundaries case -> legend select survives while outside select is absent -> fieldset assertion
- live DOM recalculation, add/move/selected changes, and snapshot isolation -> dynamic case -> each read reflects current DOM and old list stays unchanged -> dynamic assertions
Each assertion is designed to reject an implementation that takes only the first selected option, ignores optgroup inheritance, caches state, merges duplicate names, or aliases a returned list.
"""
import argparse
import os
import subprocess
import sys
import tempfile
from pathlib import Path

# The verifier launches this file from its directory; make the workspace importable before any product import.
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

JAVA_SOURCE = r'''import java.util.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.Connection;

public class FormDataAcceptance {
    static void fail(String m) { throw new AssertionError(m); }
    static void check(boolean ok, String m) { if (!ok) fail(m); }
    static FormElement form(String html) {
        Document d = Jsoup.parse(html);
        return (FormElement) d.selectFirst("form");
    }
    static void expect(FormElement f, String... wanted) {
        List<Connection.KeyVal> got = f.formData();
        check(got.size() == wanted.length, "size expected=" + wanted.length + " got=" + got);
        for (int i = 0; i < wanted.length; i++)
            check(wanted[i].equals(got.get(i).toString()), "at " + i + " expected=" + wanted[i] + " got=" + got.get(i));
        System.out.println(got);
    }
    static void boundaries() {
        // Wrong implementation caught: selected values in a disabled optgroup or disabled option must not leak.
        FormElement f = form("<form><input name=before value=x>" +
            "<select name=multi multiple><option value=a selected>" +
            "<optgroup disabled><option value=b selected><option value=c selected></optgroup>" +
            "<option value=d selected disabled><optgroup><option value=e selected><option value=f></optgroup>" +
            "</select><input name=after value=y></form>");
        expect(f, "before=x", "multi=a", "multi=e", "after=y");

        // Wrong implementation caught: taking a disabled selected option instead of the first enabled DOM option.
        FormElement singles = form("<form><select name=one><optgroup disabled><option value=a selected></optgroup><option value=b></select>" +
            "<select name=two><optgroup disabled><option value=c selected><option value=d></optgroup></select>" +
            "<select name=three><optgroup disabled><option value=e selected></optgroup><optgroup><option value=f></optgroup></select></form>");
        expect(singles, "one=b", "three=f");

        // Wrong implementation caught: fieldset allowance must not bypass optgroup filtering or admit controls outside the first legend.
        FormElement fs = form("<form><fieldset disabled><legend><select name=inside multiple>" +
            "<optgroup disabled><option value=blocked selected></optgroup><option value=ok selected></select></legend>" +
            "<select name=outside><option value=wrong selected></select></fieldset></form>");
        expect(fs, "inside=ok");
    }

