import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class Accept {
  static int failures = 0;
  static void eq(Object want, Object got, String msg) {
    if (!want.equals(got)) { failures++; System.out.println("FAIL " + msg + "\n  want: " + esc(want) + "\n  got:  " + esc(got)); }
  }
  static void ok(boolean b, String msg) { if (!b) { failures++; System.out.println("FAIL " + msg); } }
  static String esc(Object o) { String s = String.valueOf(o); StringBuilder b = new StringBuilder();
    for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); b.append(c < 32 || c > 126 ? String.format("\\u%04x", (int)c) : c); } return b.toString(); }

  public static void main(String[] a) {
    // 1. RCDATA: tags/attrs/stray < are text, no child elements
    Document d = Jsoup.parse("<title><b class=x>bold</b> a<b</title>");
    Element t = d.expectFirst("title");
    eq(0, t.childNodeSize() == 1 ? 0 : 1, "title has single text child");
    eq("<b class=x>bold</b> a<b", t.wholeText(), "title content is text");
    d = Jsoup.parse("<textarea rows=2><div>x</div><notatag</textarea>");
    eq("<div>x</div><notatag", d.expectFirst("textarea").wholeText(), "textarea content is text");

    // 2. only matching end tag, case-insensitive; siblings keep order
    d = Jsoup.parse("<title>x</other>y</TiTLE><p>one</p><p>two</p>");
    eq("x</other>y", d.expectFirst("title").wholeText(), "non-matching end tag is text");
    eq("one", d.body().child(0).text(), "sibling 1 after rcdata");
    eq("two", d.body().child(1).text(), "sibling 2 after rcdata");
    d = Jsoup.parse("<textarea>a</TEXTAREA><i>b</i>");
    eq("a", d.expectFirst("textarea").wholeText(), "case-insensitive end tag");
    eq("b", d.expectFirst("i").text(), "sibling after textarea");

    // 3. numeric refs: dec, hex, X case, missing semicolon
    eq("ABCD", Jsoup.parse("<title>&#65;&#x42;&#X43;&#68</title>").expectFirst("title").wholeText(), "numeric refs decode");
    eq("AB", Jsoup.parse("<textarea>&#x41&#66;</textarea>").expectFirst("textarea").wholeText(), "semicolonless hex");

    // 4. invalid -> U+FFFD, doesn't swallow following; consecutive handled individually
    eq("�X", Jsoup.parse("<title>&#0;X</title>").expectFirst("title").wholeText(), "null ref -> FFFD + next char");
    eq("�A�B", Jsoup.parse("<title>&#0;&#65;&#xD800;B</title>").expectFirst("title").wholeText(), "consecutive valid/invalid");
    eq("�", Jsoup.parse("<title>&#x110000;</title>").expectFirst("title").wholeText(), "out of range -> FFFD");
    eq("A�B", Jsoup.parse("<textarea>A&#0;B</textarea>").expectFirst("textarea").wholeText(), "null ref in textarea");

    // 5. invalid fragments preserved
    eq("&#;&#x;&#xg;&#g;", Jsoup.parse("<title>&#;&#x;&#xg;&#g;</title>").expectFirst("title").wholeText(), "invalid refs literal");

    // 6/7. textarea/title stability incl. newlines, entities, angle brackets
    String[] texts = {"line1\nline2 <notatag", "a&amp;b<c", "\nA", "\r\nA", "\n\nA", "\rA", "x</textarea-ish>"};
    for (String text : texts) {
      for (String tag : new String[]{"textarea", "title"}) {
        String html = "<" + tag + ">" + text + "</" + tag + ">";
        Document doc = Jsoup.parse(html);
        doc.outputSettings().prettyPrint(false);
        Element el = doc.expectFirst(tag);
        String outer = el.outerHtml();
        String again = Jsoup.parse(outer).expectFirst(tag).wholeText();
        eq(el.wholeText(), again, tag + " round-trip stable for " + esc(text));
        eq(el.wholeText(), Jsoup.parse(html).expectFirst(tag).wholeText(), tag + " repeat parse stable");
      }
    }
    // initial LF consumed by parser, restored on serialization
    eq("A", Jsoup.parse("<textarea>\nA</textarea>").expectFirst("textarea").wholeText(), "initial LF consumed");
    eq("<textarea>\nA</textarea>", Jsoup.parse("<textarea>\nA</textarea>").expectFirst("textarea").outerHtml(), "initial LF restored in html");
    eq("\nA", Jsoup.parse("<textarea>\n\nA</textarea>").expectFirst("textarea").wholeText(), "only one LF consumed");

    // 8. script/style rawtext: literal regardless of attrs/case
    eq("&#65;&amp;<b>", Jsoup.parse("<script type='text/javascript'>&#65;&amp;<b></script>").expectFirst("script").data(), "script literal");
    eq("&#65;&amp;<b>", Jsoup.parse("<SCRIPT>&#65;&amp;<b></SCRIPT>").expectFirst("script").data(), "script literal uppercase");
    eq("&#65;&lt;", Jsoup.parse("<style media=x>&#65;&lt;</style>").expectFirst("style").data(), "style literal");
    eq("&#65;&lt;", Jsoup.parse("<STYLE>&#65;&lt;</STYLE>").expectFirst("style").data(), "style literal uppercase");

    // 9. after RCDATA: elements/attrs/order unchanged
    d = Jsoup.parse("<title>t</title><div B=1 a='2'>x</div><span>s</span>");
    Element div = d.expectFirst("div");
    eq("1", div.attr("b"), "attr name normalized");
    eq("2", div.attr("a"), "attr 2");
    eq("span", div.nextElementSibling().tagName(), "doc order after title");

    // 10. missing end tag -> text to EOF, no exception
    eq("no end <b>", Jsoup.parse("<title>no end <b>").expectFirst("title").wholeText(), "unclosed title to EOF");
    eq("no end <b>", Jsoup.parse("<textarea>no end <b>").expectFirst("textarea").wholeText(), "unclosed textarea to EOF");
    eq("no end <b>", Jsoup.parse("<script>no end <b>").expectFirst("script").data(), "unclosed script to EOF");

    // 11. whole-document serialize -> reparse stable
    String[] docs = {
      "<title>a<b&#0;</title><p>x</p>",
      "<textarea>\ntwo\nlines &amp; <b</textarea><i>s</i>",
      "<script>&#65;<b></script><style>&amp;</style><p>after</p>",
      "<pre>\nkeep\n</pre><textarea>\n\nA</textarea>",
    };
    for (String h : docs) {
      Document d1 = Jsoup.parse(h);
      String s1 = d1.outerHtml();
      String s2 = Jsoup.parse(s1).outerHtml();
      eq(s1, s2, "doc round-trip stable: " + esc(h));
      Document flat = Jsoup.parse(h);
      flat.outputSettings().prettyPrint(false);
      String f1 = flat.outerHtml();
      Document flat2 = Jsoup.parse(f1);
      flat2.outputSettings().prettyPrint(false);
      eq(f1, flat2.outerHtml(), "flat round-trip stable: " + esc(h));
    }

    // 12. existing behaviors
    eq("¬", Jsoup.parse("<p>&not</p>").expectFirst("p").text(), "named entity semicolonless");
    eq("∉", Jsoup.parse("<p>&notin;</p>").expectFirst("p").text(), "named entity");
    eq("€Ÿ", Jsoup.parse("<p>&#x80;&#x9F;</p>").expectFirst("p").text(), "win1252 extension");
    ok(Jsoup.parse("<p>one<p>two").body().childNodeSize() == 2, "tag fixing: implied </p>");
    eq("A B", Jsoup.parse("<p>A\r\nB</p>").expectFirst("p").text(), "newline normalization");

    System.out.println(failures == 0 ? "ALL PASS" : failures + " FAILURES");
  }
}
